# Variant pipeline families
def family(g, mode, noise_rank=None):
    cnts=Counter(x for r in g for x in r); bg=max(cnts,key=lambda v:cnts[v])
    others=sorted([c for c in cnts if c!=bg],key=lambda cc:cnts[cc])
    g2=[r[:] for r in g]
    if mode=='delete':
        for y in range(len(g)):
            for x in range(len(g[0])):
                if g2[y][x]==others[noise_rank-1]: g2[y][x]=bg
    elif mode=='recolor_bg':
        # replace noise cells with their nearest non-bg neighbor color via BFS
        from collections import deque
        seen=[[False]*len(g[0]) for _ in g]; q=deque(); mark=[[None]*len(g[0]) for _ in g]
        for y in range(len(g)):
            for x in range(len(g[0])):
                c=g2[y][x]
                if c!=bg: seen[y][x]=True; q.append((y,x))
        dirs=((1,0),(-1,0),(0,1),(0,-1))
        while q:
            y,x=q.popleft()
            if mark[y][x] is None: mark[y][x]=g2[y][x]
            for dy,dx in dirs:
                p,q_=y+dy,x+dx
                if 0<=p<len(g) and 0<=q_<len(g[0]) and not seen[p][q_]:
                    seen[p][q_]=True; q.append((p,q_)); mark[p][q_]=mark[y][x]
        for y in range(len(g)):
            for x in range(len(g[0])):
                if g2[y][x]==others[noise_rank-1]: g2[y][x]=mark[y][x] if mark[y][x] is not None else bg
    kept=[x for x in range(len(g[0])) if any(g2[y][x]!=bg for y in range(len(g)))]
    return [[g2[y][x] for x in kept] for y in range(len(g))]

