def solve(gi, noise_rank=None):
    H,W=len(gi),len(gi[0])
    cnts=Counter(x for r in gi for x in r); bg=max(cnts,key=lambda v:cnts[v])
    others=sorted([c for c in cnts if c!=bg],key=lambda cc:cnts[cc])
    g2=[r[:] for r in gi]
    # multi-source BFS over all non-noise non-bg colors
    cno=others[noise_rank-1] if noise_rank is not None else others[0]
    q=deque(); seen=[[False]*W for _ in range(H)]; lab=[[None]*W for _ in range(H)]
    for y in range(H):
        for x in range(W):
            if gi[y][x]!=bg and gi[y][x]!=cno:
                seen[y][x]=True; q.append((y,x)); lab[y][x]=gi[y][x]
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    while q:
        p,px=q.popleft()
        for dy,dx in dirs:
            ny,nx=p+dy,px+dx
            if 0<=ny<H and 0<=nx<W and not seen[ny][nx]:
                seen[ny][nx]=True; q.append((ny,nx)); lab[ny][nx]=lab[p][px]
    for y in range(H):
        for x in range(W):
            if gi[y][x]==cno:
                lab[y][x]=lab[y][x] if lab[y][x] is not None else bg
    kept=[x for x in range(W) if any(lab[y][x]!=bg for y in range(H))]
    return [[lab[y][x] for x in kept] for y in range(H)],(cno,len(kept))

