def solve(gi, cno_idx, diag=False):
    H,W=len(gi),len(gi[0])
    cnts=Counter(x for r in gi for x in r); bg=max(cnts,key=lambda v:cnts[v])
    others=sorted([c for c in cnts if c!=bg],key=lambda cc:cnts[cc])
    cno=others[cno_idx-1]
    lab=[[None]*W for _ in range(H)]; seen=[[False]*W for _ in range(H)]; q=deque()
    dirs=((1,0),(-1,0),(0,1),(0,-1)) if not diag else ((1,1),(1,-1),(-1,1),(-1,-1))
    for y in range(H):
        for x in range(W):
            if gi[y][x]!=bg and gi[y][x]!=cno:
                seen[y][x]=True; q.append((y,x)); lab[y][x]=gi[y][x]
    while q:
        p,q_=q.popleft()
        for dy,dx in dirs:
            ny,nx=p+dy,q_+dx
            if 0<=ny<H and 0<=nx<W and not seen[ny][nx]:
                seen[ny][nx]=True; q.append((ny,nx)); lab[ny][nx]=lab[p][q_]
    g2=[[lab[y][x] if gi[y][x]==cno else gi[y][x] for x in range(W)] for y in range(H)]
    kept=[x for x in range(W) if any(g2[y][x]!=bg for y in range(H))]
    return [[g2[y][x] for x in kept] for y in range(H)],(cno,len(kept))
